input.sparql:
SELECT DISTINCT ?work ?workLabel ?author ?year WHERE {
  ?work wdt:P921 wd:Q17167 .  # main subject: Roman Republic
  ?work wdt:P921/wdt:P279* wd:Q735 .  # also about art or artistic concepts
  OPTIONAL { ?work wdt:P50 ?author }
  OPTIONAL { ?work wdt:P577 ?pubdate }
  BIND(YEAR(?pubdate) as ?year)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" }
} LIMIT 20

SELECT DISTINCT ?work ?workLabel ?lcsh ?fast WHERE {
  {
    ?work wdt:P921 wd:Q17167 .  # Roman Republic
    ?work wdt:P921 ?artTopic .
    ?artTopic wdt:P31*/wdt:P279* wd:Q735 .  # art
  } UNION {
    ?work wdt:P921 wd:Q8740 .  # Roman art
  } UNION {
    ?work wdt:P921 wd:Q2038848 .  # Roman sculpture  
  } UNION {
    ?work wdt:P921 wd:Q2413079 .  # Roman painting
  }
  OPTIONAL { ?work wdt:P244 ?lcsh }
  OPTIONAL { ?work wdt:P2163 ?fast }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" }
} LIMIT 25

