SELECT DISTINCT ?concept ?conceptLabel ?description WHERE {
  VALUES ?concept {
    wd:Q2413079    # Roman painting
    wd:Q2038848    # Roman sculpture  
    wd:Q8740       # Roman art
    wd:Q3344524    # Roman portraiture
    wd:Q1139665    # triumphal painting
    wd:Q780548     # fabula praetexta
    wd:Q17049      # fresco
    wd:Q179700     # mosaic
    wd:Q838948     # relief
  }
  OPTIONAL { ?concept schema:description ?description . FILTER(LANG(?description) = "en") }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" }
